def segment_and_annotate(sentence_id: str, text: str) -> List[Dict[str, Any]]:
    tokens: List[Dict[str, Any]] = []
    i = 0
    n = len(text)
    token_idx = 0
    word_idx = 0
    max_word_len = max((len(w) for w in CONTEXT_WORD_DICT), default=1)

    while i < n:
        matched_word = None
        for length in range(min(max_word_len, n - i), 1, -1):
            candidate = text[i : i + length]
            if candidate in CONTEXT_WORD_DICT:
                matched_word = candidate
                break

        if matched_word:
            pinyins, poly_flags = CONTEXT_WORD_DICT[matched_word]
            for char_offset, ch in enumerate(matched_word):
                py = pinyins[char_offset]
                is_poly = poly_flags[char_offset]
                tokens.append(
                    {
                        "id": f"{sentence_id}_t{token_idx:02d}",
                        "token_index": token_idx,
                        "character": ch,
                        "pinyin": py,
                        "word": matched_word,
                        "word_index": word_idx,
                        "audio_url": "",
                        "is_polyphone": is_poly,
                        "proofread_status": "verified",
                    }
                )
                token_idx += 1
            i += len(matched_word)
            word_idx += 1
        else:
            ch = text[i]
            py, is_poly = SINGLE_CHAR_DICT.get(ch, (ch, False))
            tokens.append(
                {
                    "id": f"{sentence_id}_t{token_idx:02d}",
                    "token_index": token_idx,
                    "character": ch,
                    "pinyin": py,
                    "word": ch,
                    "word_index": word_idx,
                    "audio_url": "",
                    "is_polyphone": is_poly,
                    "proofread_status": "verified",
                }
            )
            token_idx += 1
            word_idx += 1
            i += 1

    return tokens


def generate_svg_illustration(theme: str, sentence_text: str, page_idx: int, total_pages: int = 5) -> bytes:
    """
    Generates a text-free, character-consistent picture-book SVG illustration (PRD Section 5.1:
    consistent protagonist appearance + no text revealing the sentence answer).
    """
    is_night = any(k in theme or k in sentence_text for k in ("太空", "星", "月", "夜"))
    is_ocean = any(k in theme or k in sentence_text for k in ("海", "贝壳", "沙滩"))
    bg_top = "#1a237e" if is_night else ("#e0f7fa" if is_ocean else "#e8f5e9")
    bg_bottom = "#283593" if is_night else ("#80deea" if is_ocean else "#c8e6c9")
    orb_color = "#fff59d" if is_night else "#ffd54f"

    has_water = any(k in sentence_text for k in ("河", "水", "海")) or is_ocean
    has_bridge = "桥" in sentence_text
    has_friend = any(k in sentence_text for k in ("鹿", "恐龙", "朋友"))

    bear_x = 160 + (page_idx * 420) // max(1, total_pages - 1)
    bear_y = 225 if (has_bridge and 2 <= page_idx <= 3) else 255

    parts = [
        f'<svg xmlns="http://www.w3.org/2000/svg" width="800" height="420" viewBox="0 0 800 420">',
        f'<defs><linearGradient id="sky" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="{bg_top}"/><stop offset="100%" stop-color="{bg_bottom}"/></linearGradient></defs>',
        '<rect width="800" height="420" rx="24" fill="url(#sky)"/>',
        f'<circle cx="690" cy="82" r="42" fill="{orb_color}"/>',
        '<path d="M0 310 Q 200 220 420 310 T 800 300 L 800 420 L 0 420 Z" fill="#81c784" opacity="0.55"/>',
        '<g><rect x="85" y="210" width="16" height="65" fill="#6d4c41"/><circle cx="93" cy="195" r="38" fill="#43a047"/><rect x="695" y="200" width="18" height="75" fill="#6d4c41"/><circle cx="704" cy="182" r="42" fill="#2e7d32"/></g>',
    ]
    if has_water:
        parts.append('<path d="M0 325 Q 200 295 400 325 T 800 320 L 800 420 L 0 420 Z" fill="#29b6f6" opacity="0.78"/>')
        parts.append('<path d="M80 355 Q 140 345 200 355 M 380 365 Q 450 352 520 365" stroke="#e1f5fe" stroke-width="4" stroke-linecap="round" fill="none"/>')
    if has_bridge:
        parts.append('<path d="M230 330 Q 400 245 570 330" stroke="#8d6e63" stroke-width="26" fill="none" stroke-linecap="round"/>')
    if has_friend:
        fx = bear_x + 115 if bear_x + 115 <= 650 else bear_x - 115
        parts.append(
            f'<g transform="translate({fx}, 235)"><ellipse cx="0" cy="45" rx="26" ry="34" fill="#ffb74d"/><circle cx="0" cy="2" r="22" fill="#ffcc80"/><circle cx="-7" cy="0" r="3" fill="#3e2723"/><circle cx="7" cy="0" r="3" fill="#3e2723"/></g>'
        )
    parts.append(
        f'<g transform="translate({bear_x}, {bear_y})">'
        '<circle cx="-18" cy="-22" r="11" fill="#795548"/><circle cx="18" cy="-22" r="11" fill="#795548"/>'
        '<ellipse cx="0" cy="36" rx="28" ry="32" fill="#8d6e63"/><ellipse cx="0" cy="38" rx="18" ry="22" fill="#d7ccc8"/>'
        '<circle cx="0" cy="0" r="25" fill="#8d6e63"/><ellipse cx="0" cy="6" rx="11" ry="8" fill="#efebe9"/>'
        '<circle cx="-8" cy="-4" r="3.5" fill="#212121"/><circle cx="8" cy="-4" r="3.5" fill="#212121"/>'
        '<path d="M-20 18 Q 0 26 20 18" stroke="#fbc02d" stroke-width="9" stroke-linecap="round" fill="none"/>'
        "</g></svg>"
    )
    return "\n".join(parts).encode("utf-8")


def build_default_sample_manifest() -> Dict[str, Any]:
    story_id = "story_xiaoxiong_guohe"
    version_id = "ver_xiaoxiong_v1"

    raw_sentences = [
        "小熊来到一条小河边。",
        "他看着哗哗流淌的河水，心里有点着急。",
        "鹿阿姨走过来温和地告诉他：前面有一座木桥可以安全通行。",
        "木桥上留下一行脚印，小熊勇敢地迈开脚步行走。",
        "小熊稳稳地走过木桥，到达对岸的森林，开心极了！",
    ]

    sentences_manifest = []
    for idx, text in enumerate(raw_sentences):
        sent_id = f"{version_id}_s{idx:02d}"
        tokens = segment_and_annotate(sent_id, text)
        sentences_manifest.append(
            {
                "id": sent_id,
                "sequence_index": idx,
                "text": text,
                "image_url": f"/media/stories/{story_id}/{version_id}/page_{idx:02d}.svg",
                "audio_url": "",
                "tokens": tokens,
            }
        )

    full_text = "\n".join(raw_sentences)
    checksum = hashlib.sha256(full_text.encode("utf-8")).hexdigest()

    return {
        "story_id": story_id,
        "title": "小熊过河",
        "theme": "勇气与探索（森林过河）",
        "description": "小熊在鹿阿姨的帮助下找到木桥，勇敢过河的趣味故事（含多音字“行/着”语境注音校验）。",
        "cover_url": f"/media/stories/{story_id}/{version_id}/page_00.svg",
        "version_id": version_id,
        "version_number": 1,
        "checksum": checksum,
        "status": "published",
        "sentences": sentences_manifest,
    }


def create_story_zip(output_path: str, manifest: Dict[str, Any] = None, images_dir: str = None) -> Dict[str, Any]:
    if manifest is None:
        manifest = build_default_sample_manifest()

    os.makedirs(os.path.dirname(os.path.abspath(output_path)), exist_ok=True)
    story_id = manifest["story_id"]
    version_id = manifest["version_id"]
    total_pages = len(manifest["sentences"])

    user_images: List[str] = []
    if images_dir and os.path.isdir(images_dir):
        valid_exts = (".jpg", ".jpeg", ".png", ".webp", ".svg", ".gif")
        user_images = sorted(
            [
                os.path.join(images_dir, fn)
                for fn in os.listdir(images_dir)
                if fn.lower().endswith(valid_exts)
            ]
        )

    if user_images:
        for idx, sent in enumerate(manifest["sentences"]):
            img_idx = min(len(user_images) - 1, (idx * len(user_images)) // max(1, total_pages))
            ext = os.path.splitext(user_images[img_idx])[1].lower()
            sent["image_url"] = f"/media/stories/{story_id}/{version_id}/page_{idx:02d}{ext}"
        manifest["cover_url"] = manifest["sentences"][0]["image_url"]

    with zipfile.ZipFile(output_path, "w", compression=zipfile.ZIP_DEFLATED) as zf:
        zf.writestr("manifest.json", json.dumps(manifest, ensure_ascii=False, indent=2))
        for idx, sent in enumerate(manifest["sentences"]):
            if user_images:
                img_idx = min(len(user_images) - 1, (idx * len(user_images)) // max(1, total_pages))
                ext = os.path.splitext(user_images[img_idx])[1].lower()
                zf.write(user_images[img_idx], f"media/stories/{story_id}/{version_id}/page_{idx:02d}{ext}")
            else:
                svg_bytes = generate_svg_illustration(manifest.get("theme", ""), sent["text"], idx, total_pages)
                zf.writestr(f"media/stories/{story_id}/{version_id}/page_{idx:02d}.svg", svg_bytes)
            zf.writestr(f"media/audio/{sent['id']}_full.mp3", b"ID3\x03\x00\x00\x00\x00\x00\x00" + b"\x00" * 256)
            for tok in sent["tokens"]:
                if tok.get("audio_url"):
                    rel_audio = tok["audio_url"].lstrip("/")
                    zf.writestr(rel_audio, b"ID3\x03\x00\x00\x00\x00\x00\x00" + b"\x00" * 128)

    return manifest


def main() -> None:
    parser = argparse.ArgumentParser(description="Package a proofread story into an offline .zip bundle.")
    parser.add_argument("--output", "-o", default="dist/story_xiaoxiong_v1.zip", help="Output zip path")
    parser.add_argument("--images-dir", "-i", default=None, help="Directory of user-prepared images sorted by filename")
    args = parser.parse_args()
    manifest = create_story_zip(args.output, images_dir=args.images_dir)
    print(f"[story_packager] packaged '{manifest['title']}' ({manifest['version_id']}) -> {args.output}")


if __name__ == "__main__":
    main()
